export const tree =
  '// A hierarchy as a tidy tree: "right" grows left to right (deep trees, file trees), "down" grows top down (org charts).\n// Leaves get one slot each and parents center over their children. Tap a node\'s +/− knob to collapse or expand it,\n// tap a node to select it (tap it again to toggle it). With `choose`, the Choose button submits the selected node.\n\nconst ROW = 36\nconst LEVEL = 70\n// A fully expanded large tree stops drawing nodes here, under the spec\'s 2,000 commands per frame.\nconst BUDGET = 1900\nconst PALETTE = ["accent", "#f59e0b", "#10b981", "#ef4444", "#8b5cf6", "#06b6d4", "#ec4899", "#84cc16"]\n\n// Large trees start collapsed below `expand` levels (default: all open up to 40 nodes, else 2 levels).\nfunction init(data) {\n  const collapsed = []\n  const count = (node) => 1 + (node.children ?? []).reduce((sum, child) => sum + count(child), 0)\n  const expand = data.expand ?? (count(data.root) > 40 ? 2 : Infinity)\n  const close = (node, key, depth) => {\n    if (!node.children) return\n    if (depth >= expand) collapsed.push(key)\n    else node.children.forEach((child, index) => close(child, join(key, index), depth + 1))\n  }\n  close(data.root, "", 0)\n  return { collapsed, selected: null }\n}\n\nfunction view(state, data) {\n  const tree = layout(data, state)\n  const picked = state.selected === null ? null : tree.items.find((item) => item.key === state.selected)\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: data.orientation === "down" ? tree.depth * LEVEL + 8 : Math.max(60, tree.leaves * ROW + 8),\n      fps: 60,\n      duration: intro(tree),\n      alt: summary(data),\n    }),\n    ui.text(picked ? describe(data, picked) : "Tap a node to select it; tap its +/− to collapse or expand it", {\n      style: "caption",\n      tone: picked ? "default" : "muted",\n    }),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button(picked ? "Choose " + picked.node.label : "Choose", {\n          onPress: (state) => choose(state, data),\n          variant: "primary",\n          disabled: !picked,\n        }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null) {\n    const picked = layout(data, state).items.find((item) => item.key === state.selected)\n    return submit({ label: picked.node.label, path: trail(data, picked.key), note: picked.node.note })\n  }\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  if (pointer.kind !== "up") return state\n  const tree = layout(data, state)\n  const hit = locate(data, tree, place(data, tree, pointer.width), pointer.x, pointer.y)\n  if (!hit) return { ...state, selected: null }\n  const toggle = hit.knob || (hit.item.key === state.selected && hit.item.node.children)\n  const collapsed = !toggle\n    ? state.collapsed\n    : state.collapsed.includes(hit.item.key)\n      ? state.collapsed.filter((key) => key !== hit.item.key)\n      : [...state.collapsed, hit.item.key]\n  return { collapsed, selected: hit.knob ? state.selected : hit.item.key }\n}\n\nfunction draw(state, data, frame) {\n  const g = ui.draw()\n  const tree = layout(data, state)\n  const at = place(data, tree, frame.width)\n  const hover = frame.pointer && !frame.pointer.down ? locate(data, tree, at, frame.pointer.x, frame.pointer.y) : null\n  const down = data.orientation === "down"\n  // One alpha group per depth, so levels fade in one after another.\n  for (let depth = 0; depth < tree.depth; depth++) {\n    const fade = ease((frame.t - depth * 0.12) / 0.35)\n    if (fade <= 0) break\n    g.save().alpha(fade)\n    tree.items.forEach((item, index) => {\n      if (item.depth !== depth || g.commands.length > BUDGET) return\n      const box = at[index]\n      if (item.parent >= 0) {\n        const from = at[item.parent]\n        if (down) {\n          const mid = (from.y + from.h + box.y) / 2\n          g.path(\n            [\n              ["M", from.x + from.w / 2, from.y + from.h],\n              ["C", from.x + from.w / 2, mid, box.x + box.w / 2, mid, box.x + box.w / 2, box.y],\n            ],\n            { stroke: "border", width: 1.5 },\n          )\n        } else {\n          const mid = (from.x + from.w + box.x) / 2\n          g.path(\n            [\n              ["M", from.x + from.w, from.y + from.h / 2],\n              ["C", mid, from.y + from.h / 2, mid, box.y + box.h / 2, box.x, box.y + box.h / 2],\n            ],\n            { stroke: "border", width: 1.5 },\n          )\n        }\n      }\n      const selected = item.key === state.selected\n      const hovered = hover && hover.item.key === item.key\n      const accent = item.node.color ?? PALETTE[(item.branch < 0 ? 0 : item.branch) % PALETTE.length]\n      g.rrect(box.x, box.y, box.w, box.h, 6, {\n        fill: "surface",\n        stroke: selected ? accent : hovered ? "muted" : "border",\n        width: selected ? 2 : 1,\n      })\n      g.rrect(box.x, box.y, 4, box.h, 2, accent)\n      const lines = item.node.note && box.h > 30\n      g.text(box.x + 11, box.y + (lines ? 15 : box.h / 2 + 4), fit(item.node.label, box.w - 16, 12), {\n        size: 12,\n        weight: depth === 0 || selected ? 600 : 400,\n      })\n      if (lines) g.text(box.x + 11, box.y + 30, fit(item.node.note, box.w - 16, 11), { size: 11, color: "muted" })\n      if (item.node.children) {\n        const knob = knobAt(data, box)\n        const closed = state.collapsed.includes(item.key)\n        g.circle(knob.x, knob.y, 7, { fill: closed ? accent : "bg", stroke: closed ? accent : "border", width: 1 })\n        g.text(knob.x, knob.y + 4, closed ? "+" : "−", {\n          size: 11,\n          weight: 600,\n          align: "center",\n          color: closed ? "#ffffff" : "muted",\n        })\n      }\n    })\n    g.restore()\n  }\n  return g.commands\n}\n\n// The visible tree in slots: each item has a depth, a breadth slot, its parent\'s index and its top-level branch.\nfunction layout(data, state) {\n  const items = []\n  let leaves = 0\n  let depth = 0\n  const walk = (node, key, level, parent, branch) => {\n    const index = items.length\n    items.push({ key, node, depth: level, parent, branch, slot: 0 })\n    depth = Math.max(depth, level + 1)\n    if (node.children && !state.collapsed.includes(key)) {\n      const slots = node.children.map((child, at) =>\n        walk(child, join(key, at), level + 1, index, level === 0 ? at : branch),\n      )\n      items[index].slot = (slots[0] + slots[slots.length - 1]) / 2\n    } else items[index].slot = leaves++\n    return items[index].slot\n  }\n  walk(data.root, "", 0, -1, -1)\n  return { items, leaves, depth }\n}\n\n// Pixel boxes for the layout at a canvas width; notes show only in the taller "down" boxes.\nfunction place(data, tree, width) {\n  if (data.orientation === "down") {\n    const slot = (width - 16) / tree.leaves\n    const w = Math.max(40, Math.min(150, slot - 10))\n    const h = tree.items.some((item) => item.node.note) ? 40 : 28\n    return tree.items.map((item) => ({ x: 8 + (item.slot + 0.5) * slot - w / 2, y: 6 + item.depth * LEVEL, w, h }))\n  }\n  const column = (width - 16) / tree.depth\n  const w = Math.max(50, Math.min(170, column - 28))\n  const h = 26\n  return tree.items.map((item) => ({ x: 8 + item.depth * column, y: 4 + item.slot * ROW + (ROW - h) / 2, w, h }))\n}\n\nfunction knobAt(data, box) {\n  return data.orientation === "down"\n    ? { x: box.x + box.w / 2, y: box.y + box.h }\n    : { x: box.x + box.w, y: box.y + box.h / 2 }\n}\n\nfunction locate(data, tree, at, px, py) {\n  for (let index = tree.items.length - 1; index >= 0; index--) {\n    const box = at[index]\n    const item = tree.items[index]\n    if (item.node.children) {\n      const knob = knobAt(data, box)\n      if (Math.hypot(px - knob.x, py - knob.y) <= 11) return { item, knob: true }\n    }\n    if (px >= box.x && px <= box.x + box.w && py >= box.y && py <= box.y + box.h) return { item, knob: false }\n  }\n  return null\n}\n\nfunction intro(tree) {\n  return Math.round((0.35 + 0.12 * (tree.depth - 1)) * 100) / 100\n}\n\nfunction join(key, index) {\n  return key === "" ? String(index) : key + "." + index\n}\n\nfunction trail(data, key) {\n  const labels = [data.root.label]\n  if (key === "") return labels\n  key.split(".").reduce((node, index) => {\n    labels.push(node.children[Number(index)].label)\n    return node.children[Number(index)]\n  }, data.root)\n  return labels\n}\n\nfunction describe(data, item) {\n  const count = (node) => (node.children ?? []).reduce((sum, child) => sum + 1 + count(child), 0)\n  const below = count(item.node)\n  return (\n    trail(data, item.key).join(" › ") +\n    (item.node.note ? " · " + item.node.note : "") +\n    (below ? " · " + below + (below === 1 ? " node below" : " nodes below") : "")\n  )\n}\n\nfunction summary(data) {\n  const lines = []\n  const walk = (node, depth) => {\n    if (lines.length < 60) lines.push("  ".repeat(depth) + node.label + (node.note ? " (" + node.note + ")" : ""))\n    node.children?.forEach((child) => walk(child, depth + 1))\n  }\n  walk(data.root, 0)\n  return "Tree:\\n" + lines.join("\\n")\n}\n\nfunction fit(text, width, size) {\n  const max = Math.max(1, Math.floor(width / (size * 0.58)))\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n'
export const timeline =
  '// A Gantt timeline: tasks with a start and an end (no end: a milestone), optionally in groups and with progress.\n// Dates are "YYYY-MM-DD" (an end date is inclusive) or "YYYY-MM-DDTHH:MM"; plain numbers work too (week 1, 2...).\n// `today` draws a marker (programs can\'t read the clock). Bars grow in; tap a bar to select it. With `choose`, the\n// Choose button submits the selected task.\n\nconst ROW = 26\nconst TOP = 26\nconst INTRO = 0.7\nconst MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]\nconst PALETTE = ["accent", "#f59e0b", "#10b981", "#ef4444", "#8b5cf6", "#06b6d4", "#ec4899", "#84cc16"]\n\n// Rows (group headers, then their tasks) and the time range are computed once.\nfunction init(data) {\n  const groups = [...new Set(data.tasks.map((task) => task.group ?? ""))]\n  const rows = groups.flatMap((group) => [\n    ...(group ? [{ group }] : []),\n    ...data.tasks.flatMap((task, index) => ((task.group ?? "") === group ? [{ task: index }] : [])),\n  ])\n  const spans = data.tasks.map((task) => span(task))\n  const today = data.today === undefined ? null : time(data.today, false)\n  const low = Math.min(...spans.map((item) => item.start), today ?? Infinity)\n  const high = Math.max(...spans.map((item) => item.end), today ?? -Infinity)\n  const pad = (high - low || 1) * 0.03\n  const dates = typeof data.tasks[0].start === "string"\n  return { selected: null, rows, spans, groups, dates, today, low: low - pad, high: high + pad }\n}\n\nfunction view(state, data) {\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: TOP + state.rows.length * ROW + 6,\n      fps: 60,\n      duration: INTRO,\n      alt: summary(state, data),\n    }),\n    ui.text(state.selected === null ? "Tap a bar to see its dates" : describe(state, data, state.selected), {\n      style: "caption",\n      tone: state.selected === null ? "muted" : "default",\n    }),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button("Choose task", {\n          onPress: (state) => choose(state, data),\n          variant: "primary",\n          disabled: state.selected === null,\n        }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null) {\n    const task = data.tasks[state.selected]\n    return submit({\n      label: task.label,\n      index: state.selected,\n      start: task.start,\n      end: task.end ?? task.start,\n      group: task.group,\n    })\n  }\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  pointer = below(pointer)\n  if (pointer.kind !== "up") return state\n  const row = state.rows[Math.floor((pointer.y - TOP) / ROW)]\n  const hit = pointer.y >= TOP && row && row.task !== undefined ? row.task : null\n  return { ...state, selected: hit === state.selected ? null : hit }\n}\n\nfunction draw(state, data, frame) {\n  frame = below(frame)\n  const g = ui.draw()\n  if (frame.top) g.translate(0, frame.top)\n  const box = layout(state, data, frame.width)\n  const bottom = TOP + state.rows.length * ROW\n  const today = state.today === null ? null : x(box, state.today)\n  for (const tick of ticks(state, box)) {\n    g.line(tick.x, TOP - 4, tick.x, bottom, { stroke: "border", width: 1 })\n    if (today === null || tick.x + 50 < today - 22 || tick.x > today + 22)\n      g.text(tick.x + 3, TOP - 10, tick.label, { size: 11, color: "muted" })\n  }\n  const hoverRow = frame.pointer && !frame.pointer.down ? Math.floor((frame.pointer.y - TOP) / ROW) : -1\n  state.rows.forEach((row, at) => {\n    const y = TOP + at * ROW\n    if (row.group !== undefined) {\n      const items = state.spans.filter((_, index) => (data.tasks[index].group ?? "") === row.group)\n      const from = x(box, Math.min(...items.map((item) => item.start)))\n      const to = x(box, Math.max(...items.map((item) => item.end)))\n      g.text(8, y + 17, fit(row.group, box.left - 14, 12), { size: 12, weight: 600 })\n      g.save()\n        .alpha(0.5)\n        .rrect(from, y + 11, Math.max(2, to - from), 4, 2, "muted")\n        .restore()\n      return\n    }\n    const task = data.tasks[row.task]\n    const item = state.spans[row.task]\n    const active = row.task === state.selected || at === hoverRow\n    if (active) g.save().alpha(0.08).rect(0, y, frame.width, ROW, "text").restore()\n    g.text(state.groups.length > 1 || state.groups[0] ? 18 : 8, y + 17, fit(task.label, box.left - 24, 12), {\n      size: 12,\n      weight: row.task === state.selected ? 600 : 400,\n      color: active ? "text" : "muted",\n    })\n    const fill = task.color ?? PALETTE[state.groups.indexOf(task.group ?? "") % PALETTE.length]\n    const grow = ease((frame.t - (0.3 * at) / state.rows.length) / (INTRO - 0.3))\n    if (grow <= 0) return\n    const from = x(box, item.start)\n    if (task.end === undefined) {\n      const s = 7 * grow\n      g.path(\n        [\n          ["M", from, y + ROW / 2 - s],\n          ["L", from + s, y + ROW / 2],\n          ["L", from, y + ROW / 2 + s],\n          ["L", from - s, y + ROW / 2],\n          ["Z"],\n        ],\n        fill,\n      )\n      return\n    }\n    const w = Math.max(3, (x(box, item.end) - from) * grow)\n    const progress = task.progress ?? 1\n    if (progress < 1)\n      g.save()\n        .alpha(0.35)\n        .rrect(from, y + 5, w, ROW - 10, 4, fill)\n        .restore()\n    if (progress > 0) g.rrect(from, y + 5, Math.max(3, w * progress), ROW - 10, 4, fill)\n    if (row.task === state.selected) g.rrect(from - 1.5, y + 3.5, w + 3, ROW - 7, 5, { stroke: "text", width: 1.5 })\n  })\n  if (today !== null && frame.t >= INTRO * 0.5) {\n    g.line(today, TOP - 4, today, bottom, { stroke: "error", width: 1.5 })\n    g.rrect(today - 20, 4, 40, 14, 4, "error")\n    g.text(today, 15, "Today", { size: 10, weight: 600, align: "center", color: "#ffffff" })\n  }\n  return g.commands\n}\n\nfunction layout(state, data, width) {\n  const longest = Math.max(\n    ...data.tasks.map((task) => task.label.length + 2),\n    ...state.groups.map((group) => group.length),\n  )\n  const left = Math.min(width * 0.38, 180, Math.max(80, 16 + 6.6 * longest))\n  return { left, w: Math.max(1, width - left - 12), low: state.low, high: state.high }\n}\n\nfunction x(box, value) {\n  return box.left + (box.w * (value - box.low)) / (box.high - box.low)\n}\n\n// Tick marks for the axis: hours, days, weeks, months or years for dates; nice steps for plain numbers.\nfunction ticks(state, box) {\n  const perDay = box.w / (state.high - state.low)\n  const out = []\n  if (!state.dates) {\n    const raw = 64 / perDay\n    const power = Math.pow(10, Math.floor(Math.log10(raw)))\n    const step = power * ([1, 2, 5, 10].find((factor) => factor * power >= raw) ?? 10)\n    for (let value = Math.ceil(state.low / step) * step; value <= state.high; value += step)\n      out.push({ x: x(box, value), label: String(Math.round(value * 100) / 100) })\n    return out\n  }\n  const step = [1 / 24, 3 / 24, 6 / 24, 12 / 24, 1, 2, 7, 14].find((days) => days * perDay >= 64)\n  if (step !== undefined) {\n    const first = step >= 7 ? Math.ceil((state.low + 3) / 7) * 7 - 3 : Math.ceil(state.low / step) * step\n    for (let value = first; value <= state.high; value += step)\n      out.push({\n        x: x(box, value),\n        label: step < 1 ? String(Math.round((value % 1) * 24)).padStart(2, "0") + ":00" : short(value),\n      })\n    return out\n  }\n  const months = [1, 3, 12].find((count) => count * 30.4 * perDay >= 64) ?? 12\n  let [year, month] = civil(Math.floor(state.low))\n  month = Math.ceil(month / months) * months - months + 1\n  for (let value = days(year, month, 1); value <= state.high; ) {\n    if (value >= state.low)\n      out.push({\n        x: x(box, value),\n        label: months === 12 ? String(year) : month === 1 ? MONTHS[0] + " " + year : MONTHS[month - 1],\n      })\n    month += months\n    if (month > 12) {\n      month -= 12\n      year++\n    }\n    value = days(year, month, 1)\n  }\n  return out\n}\n\n// A task\'s start and end as numbers (days since 1970 for dates). A date-only end includes that day.\nfunction span(task) {\n  const start = time(task.start, false)\n  return { start, end: task.end === undefined ? start : Math.max(start, time(task.end, true)) }\n}\n\nfunction time(value, end) {\n  if (typeof value === "number") return value\n  const [date, clock] = value.split("T")\n  const [y, m, d] = date.split("-").map(Number)\n  const [hours, minutes] = clock ? clock.split(":").map(Number) : [0, 0]\n  return days(y, m, d) + (clock ? (hours + (minutes || 0) / 60) / 24 : end ? 1 : 0)\n}\n\n// Days since 1970-01-01 in the civil calendar, and back.\nfunction days(y, m, d) {\n  const year = m <= 2 ? y - 1 : y\n  const era = Math.floor(year / 400)\n  const yoe = year - era * 400\n  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1\n  return era * 146097 + yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy - 719468\n}\n\nfunction civil(day) {\n  const z = day + 719468\n  const era = Math.floor(z / 146097)\n  const doe = z - era * 146097\n  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365)\n  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100))\n  const mp = Math.floor((5 * doy + 2) / 153)\n  const m = mp < 10 ? mp + 3 : mp - 9\n  return [yoe + era * 400 + (m <= 2 ? 1 : 0), m, doy - Math.floor((153 * mp + 2) / 5) + 1]\n}\n\nfunction short(day) {\n  const [, m, d] = civil(Math.floor(day))\n  return MONTHS[m - 1] + " " + d\n}\n\nfunction when(state, value) {\n  return state.dates ? short(value) : String(Math.round(value * 100) / 100)\n}\n\nfunction describe(state, data, index) {\n  const task = data.tasks[index]\n  const item = state.spans[index]\n  const length = item.end - item.start\n  const dates =\n    task.end === undefined\n      ? when(state, item.start) + " (milestone)"\n      : when(state, item.start) +\n        " – " +\n        when(state, state.dates && typeof task.end === "string" && !task.end.includes("T") ? item.end - 1 : item.end) +\n        (state.dates ? " (" + Math.round(length * 10) / 10 + (length === 1 ? " day)" : " days)") : "")\n  return [\n    task.label,\n    dates,\n    task.progress !== undefined ? Math.round(task.progress * 100) + "% done" : "",\n    task.group ?? "",\n  ]\n    .filter(Boolean)\n    .join(" · ")\n}\n\nfunction summary(state, data) {\n  return (\n    "Timeline of " +\n    data.tasks.length +\n    " tasks" +\n    (state.today !== null ? ", today " + when(state, state.today) : "") +\n    ". " +\n    data.tasks.map((_, index) => describe(state, data, index)).join("; ")\n  )\n}\n\nfunction fit(text, width, size) {\n  const max = Math.max(1, Math.floor(width / (size * 0.58)))\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n\n// In full screen, the layout starts below the close button when it overlaps this canvas (widgets-fullscreen.md):\n// `close` comes with the frame and the pointer, so drawing and hit testing agree.\nfunction below(area) {\n  const top = area.close ? Math.max(0, area.close.y + area.close.height) : 0\n  if (top === 0) return area\n  return {\n    ...area,\n    top,\n    height: area.height - top,\n    ...(typeof area.y === "number" ? { y: area.y - top } : {}),\n    ...(area.pointer ? { pointer: { ...area.pointer, y: area.pointer.y - top } } : {}),\n  }\n}\n'
export const funnel =
  '// A conversion funnel: stages as centered bars sized by value, joined by tapering bands, with the conversion from the\n// previous stage on the right. Bars widen in; tap a stage to select it. With `choose`, the Choose button submits it.\n\nconst ROW = 44\nconst INTRO = 0.7\n\nfunction init(data) {\n  return { selected: null }\n}\n\nfunction view(state, data) {\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: data.stages.length * ROW + 4,\n      fps: 60,\n      duration: INTRO,\n      alt: summary(data),\n    }),\n    ui.text(state.selected === null ? "Tap a stage to see its conversion" : describe(data, state.selected), {\n      style: "caption",\n      tone: state.selected === null ? "muted" : "default",\n    }),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button("Choose stage", {\n          onPress: (state) => choose(state, data),\n          variant: "primary",\n          disabled: state.selected === null,\n        }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null) {\n    const stage = data.stages[state.selected]\n    return submit({ label: stage.label, index: state.selected, value: stage.value, ...rates(data, state.selected) })\n  }\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  if (pointer.kind !== "up") return state\n  const index = Math.floor((pointer.y - 2) / ROW)\n  const hit = index >= 0 && index < data.stages.length ? index : null\n  return { ...state, selected: hit === state.selected ? null : hit }\n}\n\nfunction draw(state, data, frame) {\n  const g = ui.draw()\n  const box = layout(data, frame.width)\n  const grow = ease(frame.t / INTRO)\n  const hover = frame.pointer && !frame.pointer.down ? Math.floor((frame.pointer.y - 2) / ROW) : null\n  const active = hover !== null && hover >= 0 && hover < data.stages.length ? hover : state.selected\n  const fill = data.color ?? "accent"\n  const half = (index) => (Math.max(0.02, data.stages[index].value / box.max) * box.w * grow) / 2\n  const bar = ROW - 16\n  data.stages.forEach((stage, index) => {\n    const y = 2 + index * ROW\n    if (index > 0) {\n      const above = half(index - 1)\n      const below = half(index)\n      g.save().alpha(0.15)\n      g.path(\n        [\n          ["M", box.cx - above, y - 16 + 2],\n          ["L", box.cx + above, y - 16 + 2],\n          ["L", box.cx + below, y + 8],\n          ["L", box.cx - below, y + 8],\n          ["Z"],\n        ],\n        fill,\n      )\n      g.restore()\n    }\n    const dim = active !== null && active !== index\n    if (dim) g.save().alpha(0.5)\n    g.rrect(box.cx - half(index), y + 8, half(index) * 2, bar, 6, fill)\n    if (dim) g.restore()\n    g.text(8, y + 8 + bar / 2 - 2, fit(stage.label, box.left - 14, 12), {\n      size: 12,\n      weight: index === active ? 600 : 400,\n    })\n    g.text(8, y + 8 + bar / 2 + 13, amount(stage.value, data.unit), { size: 11, color: "muted" })\n    if (half(index) * 2 > 60)\n      g.text(box.cx, y + 8 + bar / 2 + 4, percent(stage.value / data.stages[0].value), {\n        size: 12,\n        weight: 600,\n        align: "center",\n        color: "#ffffff",\n      })\n    if (index > 0)\n      g.text(frame.width - 8, y + 8 + bar / 2 + 4, percent(stage.value / data.stages[index - 1].value), {\n        size: 12,\n        align: "right",\n        color: "muted",\n      })\n    if (index === state.selected)\n      g.rrect(box.cx - half(index) - 2, y + 6, half(index) * 2 + 4, bar + 4, 7, { stroke: "text", width: 1.5 })\n  })\n  return g.commands\n}\n\nfunction layout(data, width) {\n  const left = Math.min(\n    width * 0.3,\n    Math.max(70, 16 + 6.6 * Math.max(...data.stages.map((stage) => stage.label.length))),\n  )\n  const right = 56\n  const w = Math.max(20, width - left - right)\n  return { left, w, cx: left + w / 2, max: Math.max(...data.stages.map((stage) => stage.value), 1e-9) }\n}\n\nfunction rates(data, index) {\n  const first = data.stages[0].value\n  const previous = data.stages[Math.max(0, index - 1)].value\n  const round = (value) => Math.round(value * 1000) / 1000\n  return {\n    ofFirst: first ? round(data.stages[index].value / first) : 0,\n    ofPrevious: previous ? round(data.stages[index].value / previous) : 0,\n  }\n}\n\nfunction describe(data, index) {\n  const stage = data.stages[index]\n  const rate = rates(data, index)\n  if (index === 0) return stage.label + ": " + amount(stage.value, data.unit)\n  return (\n    stage.label +\n    ": " +\n    amount(stage.value, data.unit) +\n    " · " +\n    percent(rate.ofPrevious) +\n    " of " +\n    data.stages[index - 1].label +\n    ", " +\n    percent(rate.ofFirst) +\n    " of " +\n    data.stages[0].label +\n    " · drop-off " +\n    amount(data.stages[index - 1].value - stage.value, data.unit)\n  )\n}\n\nfunction summary(data) {\n  return (\n    "Funnel. " +\n    data.stages\n      .map(\n        (stage, index) =>\n          stage.label +\n          " " +\n          amount(stage.value, data.unit) +\n          (index ? " (" + percent(stage.value / data.stages[index - 1].value) + " of previous)" : ""),\n      )\n      .join(", ")\n  )\n}\n\nfunction percent(share) {\n  return (Number.isFinite(share) ? Math.round(share * 1000) / 10 : 0) + "%"\n}\n\nfunction amount(value, unit) {\n  const text = String(Math.round(value * 100) / 100).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ",")\n  if (!unit) return text\n  return unit.length > 1 && /^[a-z]/i.test(unit) ? text + " " + unit : text + unit\n}\n\nfunction fit(text, width, size) {\n  const max = Math.max(1, Math.floor(width / (size * 0.58)))\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n'
export const radar =
  '// A radar (spider) chart: one polygon per series over 3 to 12 axes on a shared scale. Polygons grow in; tap near an\n// axis to compare every series on it, tap a legend entry to hide a series. With `choose`, the Choose button submits the\n// selected axis with each series\' value.\n\nconst HEIGHT = 300\nconst INTRO = 0.7\nconst RINGS = 4\nconst PALETTE = ["accent", "#f59e0b", "#10b981", "#ef4444", "#8b5cf6", "#06b6d4"]\n\nfunction init(data) {\n  return { selected: null, hidden: [] }\n}\n\nfunction view(state, data) {\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: HEIGHT,\n      fps: 60,\n      duration: INTRO,\n      alt: summary(data),\n    }),\n    ui.text(\n      state.selected === null\n        ? "Tap an axis to compare the series; tap a legend entry to hide one"\n        : describe(state, data, state.selected),\n      {\n        style: "caption",\n        tone: state.selected === null ? "muted" : "default",\n      },\n    ),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button("Choose axis", {\n          onPress: (state) => choose(state, data),\n          variant: "primary",\n          disabled: state.selected === null,\n        }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null)\n    return submit({\n      axis: data.axes[state.selected],\n      index: state.selected,\n      values: Object.fromEntries(data.series.map((series) => [series.label, series.values[state.selected]])),\n    })\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  if (pointer.kind !== "up") return state\n  const box = layout(data, pointer.width, pointer.height)\n  const entry = box.legend.findIndex(\n    (item) => pointer.y >= item.y - 9 && pointer.y <= item.y + 9 && pointer.x <= box.legendRight,\n  )\n  if (entry >= 0) {\n    const hidden = state.hidden.includes(entry)\n      ? state.hidden.filter((index) => index !== entry)\n      : [...state.hidden, entry]\n    return hidden.length === data.series.length ? state : { ...state, hidden }\n  }\n  const hit = axisAt(data, box, pointer.x, pointer.y)\n  return { ...state, selected: hit === state.selected ? null : hit }\n}\n\nfunction draw(state, data, frame) {\n  const g = ui.draw()\n  const box = layout(data, frame.width, frame.height)\n  const n = data.axes.length\n  const hover = frame.pointer && !frame.pointer.down ? axisAt(data, box, frame.pointer.x, frame.pointer.y) : null\n  const active = hover ?? state.selected\n  for (let ring = 1; ring <= RINGS; ring++) {\n    const r = (box.r * ring) / RINGS\n    g.path([...data.axes.map((_, index) => [index === 0 ? "M" : "L", ...point(box, index, n, r)]), ["Z"]], {\n      stroke: "border",\n      width: 1,\n    })\n  }\n  g.text(box.cx + 4, box.cy - box.r - 4 + 12, compact(box.max), { size: 10, color: "muted" })\n  data.axes.forEach((axis, index) => {\n    const [x, y] = point(box, index, n, box.r)\n    g.line(box.cx, box.cy, x, y, { stroke: index === active ? "text" : "border", width: index === active ? 1.5 : 1 })\n    const [lx, ly] = point(box, index, n, box.r + 14)\n    const align = Math.abs(lx - box.cx) < 8 ? "center" : lx > box.cx ? "left" : "right"\n    g.text(lx, ly + 4, fit(axis, 110, 11), {\n      size: 11,\n      align,\n      weight: index === active ? 600 : 400,\n      color: index === active ? "text" : "muted",\n    })\n  })\n  const grow = ease(frame.t / INTRO)\n  data.series.forEach((series, at) => {\n    if (state.hidden.includes(at)) return\n    const color = series.color ?? PALETTE[at % PALETTE.length]\n    const points = series.values\n      .slice(0, n)\n      .map((value, index) => point(box, index, n, (box.r * Math.max(0, value) * grow) / box.max))\n    const segments = [...points.map((p, index) => [index === 0 ? "M" : "L", p[0], p[1]]), ["Z"]]\n    g.save().alpha(0.18).path(segments, color).restore()\n    g.path(segments, { stroke: color, width: 2 })\n    points.forEach((p, index) => g.circle(p[0], p[1], index === active ? 4.5 : 2.5, color))\n  })\n  data.series.forEach((series, at) => {\n    const item = box.legend[at]\n    const hidden = state.hidden.includes(at)\n    const color = series.color ?? PALETTE[at % PALETTE.length]\n    g.circle(8 + 4, item.y, 4, hidden ? { stroke: color, width: 1.5 } : color)\n    g.text(8 + 13, item.y + 4, fit(series.label, box.legendRight - 26, 12), {\n      size: 12,\n      color: hidden ? "muted" : "text",\n    })\n  })\n  return g.commands\n}\n\n// Geometry shared by draw and tap: the center and radius, the scale\'s max and the legend rows on the left.\nfunction layout(data, width, height) {\n  const legendRight =\n    data.series.length > 1 ? Math.min(140, 30 + 7 * Math.max(...data.series.map((series) => series.label.length))) : 0\n  const r = Math.max(30, Math.min(height / 2 - 30, (width - legendRight) / 2 - 70))\n  const top = data.max ?? Math.max(...data.series.flatMap((series) => series.values))\n  const legend = data.series.length > 1 ? data.series.map((_, index) => ({ y: 14 + index * 20 })) : []\n  return {\n    cx: legendRight + (width - legendRight) / 2,\n    cy: height / 2,\n    r,\n    max: data.max ?? nice(top),\n    legend,\n    legendRight,\n  }\n}\n\nfunction nice(max) {\n  if (max <= 0) return 1\n  const power = Math.pow(10, Math.floor(Math.log10(max)))\n  return power * ([1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10].find((factor) => factor * power >= max) ?? 10)\n}\n\n// Axis 0 points up; the rest follow clockwise.\nfunction point(box, index, n, r) {\n  const angle = -Math.PI / 2 + (index * Math.PI * 2) / n\n  return [box.cx + Math.cos(angle) * r, box.cy + Math.sin(angle) * r]\n}\n\nfunction axisAt(data, box, px, py) {\n  const distance = Math.hypot(px - box.cx, py - box.cy)\n  if (distance > box.r + 40 || distance < 8) return null\n  const n = data.axes.length\n  const angle = Math.atan2(py - box.cy, px - box.cx) + Math.PI / 2\n  return ((Math.round((angle / (Math.PI * 2)) * n) % n) + n) % n\n}\n\nfunction describe(state, data, index) {\n  return (\n    data.axes[index] +\n    ": " +\n    data.series\n      .filter((_, at) => !state.hidden.includes(at))\n      .map((series) => series.label + " " + amount(series.values[index], data.unit))\n      .join(", ")\n  )\n}\n\nfunction summary(data) {\n  return (\n    "Radar chart over " +\n    data.axes.join(", ") +\n    ". " +\n    data.series\n      .map((series) => series.label + ": " + series.values.map((value) => amount(value, data.unit)).join(", "))\n      .join("; ")\n  )\n}\n\nfunction amount(value, unit) {\n  const text = String(Math.round((value ?? 0) * 100) / 100)\n  if (!unit) return text\n  return unit.length > 1 && /^[a-z]/i.test(unit) ? text + " " + unit : text + unit\n}\n\nfunction compact(value) {\n  return String(Math.round(value * 100) / 100)\n}\n\nfunction fit(text, width, size) {\n  const max = Math.max(1, Math.floor(width / (size * 0.58)))\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n'
export const gauge =
  '// KPI dials: one to four gauges side by side, each a 270° arc from min to max with optional threshold bands (each band\n// runs up to `to` in a tone) and a target tick. The value arc takes the tone of its band and sweeps in while the\n// number counts up. Tap a gauge to select it. With `choose`, the Choose button submits the selected gauge.\n\nconst HEIGHT = 190\nconst INTRO = 0.9\nconst START = (Math.PI * 3) / 4\nconst SWEEP = (Math.PI * 3) / 2\n\nfunction init(data) {\n  return { selected: null }\n}\n\nfunction view(state, data) {\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: HEIGHT,\n      fps: 60,\n      duration: INTRO,\n      alt: summary(data),\n    }),\n    ui.text(state.selected === null ? "Tap a gauge for its thresholds" : describe(data.gauges[state.selected]), {\n      style: "caption",\n      tone: state.selected === null ? "muted" : "default",\n    }),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button("Choose gauge", {\n          onPress: (state) => choose(state, data),\n          variant: "primary",\n          disabled: state.selected === null,\n        }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null) {\n    const gauge = data.gauges[state.selected]\n    return submit({ label: gauge.label, index: state.selected, value: gauge.value, tone: tone(gauge, gauge.value) })\n  }\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  if (pointer.kind !== "up") return state\n  const index = Math.floor((pointer.x / pointer.width) * data.gauges.length)\n  const hit = index >= 0 && index < data.gauges.length ? index : null\n  return { ...state, selected: hit === state.selected ? null : hit }\n}\n\nfunction draw(state, data, frame) {\n  const g = ui.draw()\n  const cell = frame.width / data.gauges.length\n  const r = Math.max(24, Math.min(cell / 2 - 18, 74))\n  // The dial, its min/max and its label are 1.71 r + 54 px tall; center them vertically.\n  const top = Math.max(10, (frame.height - 1.71 * r - 54) / 2)\n  const grow = ease(frame.t / INTRO)\n  data.gauges.forEach((gauge, index) => {\n    const cx = cell * (index + 0.5)\n    const cy = top + r\n    const min = gauge.min ?? 0\n    const at = (value) => START + SWEEP * Math.max(0, Math.min(1, (value - min) / (gauge.max - min || 1)))\n    if (index === state.selected)\n      g.rrect(cx - cell / 2 + 4, 2, cell - 8, frame.height - 4, 10, { fill: "surface", stroke: "border", width: 1 })\n    g.path(arc(cx, cy, r, START, START + SWEEP), { stroke: "border", width: 10, cap: "round" })\n    let from = min\n    g.save().alpha(0.45)\n    for (const band of [...(gauge.bands ?? [])].sort((a, b) => a.to - b.to)) {\n      if (band.to > from)\n        g.path(arc(cx, cy, r + 9, at(from), at(Math.min(band.to, gauge.max))), { stroke: band.tone, width: 3 })\n      from = band.to\n    }\n    g.restore()\n    const shown = min + (gauge.value - min) * grow\n    if (shown > min)\n      g.path(arc(cx, cy, r, START, at(shown)), { stroke: tone(gauge, gauge.value), width: 10, cap: "round" })\n    if (gauge.target !== undefined) {\n      const angle = at(gauge.target)\n      g.line(\n        cx + Math.cos(angle) * (r - 9),\n        cy + Math.sin(angle) * (r - 9),\n        cx + Math.cos(angle) * (r + 9),\n        cy + Math.sin(angle) * (r + 9),\n        {\n          stroke: "text",\n          width: 2,\n          cap: "round",\n        },\n      )\n    }\n    g.text(cx, cy + 8, amount(shown, gauge.unit, gauge.value), {\n      size: Math.min(24, r / 2.6),\n      weight: 700,\n      align: "center",\n    })\n    g.text(cx - r * 0.71, cy + r * 0.71 + 16, compact(min), { size: 10, align: "center", color: "muted" })\n    g.text(cx + r * 0.71, cy + r * 0.71 + 16, compact(gauge.max), { size: 10, align: "center", color: "muted" })\n    g.text(cx, cy + r * 0.71 + 36, fit(gauge.label, cell - 16, 13), { size: 13, weight: 600, align: "center" })\n  })\n  return g.commands\n}\n\n// The band\'s tone for a value: the first band whose `to` is at or above it (default accent).\nfunction tone(gauge, value) {\n  const band = [...(gauge.bands ?? [])].sort((a, b) => a.to - b.to).find((band) => value <= band.to)\n  return band?.tone ?? "accent"\n}\n\nfunction arc(cx, cy, r, from, to) {\n  const segments = [["M", cx + Math.cos(from) * r, cy + Math.sin(from) * r]]\n  const steps = Math.max(1, Math.ceil(Math.abs(to - from) / (Math.PI / 2)))\n  const step = (to - from) / steps\n  const k = (4 / 3) * Math.tan(step / 4)\n  for (let i = 0; i < steps; i++) {\n    const a = from + i * step\n    const b = a + step\n    segments.push([\n      "C",\n      cx + r * (Math.cos(a) - k * Math.sin(a)),\n      cy + r * (Math.sin(a) + k * Math.cos(a)),\n      cx + r * (Math.cos(b) + k * Math.sin(b)),\n      cy + r * (Math.sin(b) - k * Math.cos(b)),\n      cx + r * Math.cos(b),\n      cy + r * Math.sin(b),\n    ])\n  }\n  return segments\n}\n\nfunction describe(gauge) {\n  const bands = [...(gauge.bands ?? [])].sort((a, b) => a.to - b.to)\n  const band = bands.findIndex((band) => gauge.value <= band.to)\n  return (\n    gauge.label +\n    ": " +\n    amount(gauge.value, gauge.unit) +\n    " of " +\n    compact(gauge.min ?? 0) +\n    "–" +\n    compact(gauge.max) +\n    (band >= 0\n      ? " · " +\n        bands[band].tone +\n        " band (" +\n        compact(band ? bands[band - 1].to : (gauge.min ?? 0)) +\n        "–" +\n        compact(bands[band].to) +\n        ")"\n      : "") +\n    (gauge.target !== undefined ? " · target " + amount(gauge.target, gauge.unit) : "")\n  )\n}\n\nfunction summary(data) {\n  return "Gauges. " + data.gauges.map(describe).join("; ")\n}\n\n// While counting up, show as many decimals as the final value has (at most two).\nfunction amount(value, unit, final) {\n  const digits = Math.min(2, (String(final ?? value).split(".")[1] ?? "").length)\n  const text = (Math.round(value * Math.pow(10, digits)) / Math.pow(10, digits)).toFixed(digits)\n  if (!unit) return text\n  return unit.length > 1 && /^[a-z]/i.test(unit) ? text + " " + unit : text + unit\n}\n\nfunction compact(value) {\n  const size = Math.abs(value)\n  if (size >= 1e6) return Math.round(value / 1e5) / 10 + "M"\n  if (size >= 1e4) return Math.round(value / 100) / 10 + "k"\n  return String(Math.round(value * 100) / 100)\n}\n\nfunction fit(text, width, size) {\n  const max = Math.max(1, Math.floor(width / (size * 0.58)))\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n'
export const boxplot =
  '// Box plots comparing distributions. Each group gives raw `values` (quartiles computed once in `init`, whiskers at the\n// furthest values within 1.5 × IQR, the rest drawn as outliers) or precomputed `stats`. Boxes open out from the\n// median; tap a box to read its statistics. With `choose`, the Choose button submits the selected group.\n\nconst HEIGHT = 260\nconst INTRO = 0.6\nconst PALETTE = ["accent", "#f59e0b", "#10b981", "#ef4444", "#8b5cf6", "#06b6d4", "#ec4899", "#84cc16"]\n\nfunction init(data) {\n  return {\n    selected: null,\n    stats: data.groups.map((group) =>\n      group.stats ? { ...group.stats, outliers: group.stats.outliers ?? [] } : measure(group.values),\n    ),\n  }\n}\n\nfunction view(state, data) {\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: HEIGHT,\n      fps: 60,\n      duration: INTRO,\n      alt: summary(state, data),\n    }),\n    ui.text(state.selected === null ? "Tap a box to read its statistics" : describe(state, data, state.selected), {\n      style: "caption",\n      tone: state.selected === null ? "muted" : "default",\n    }),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button("Choose group", {\n          onPress: (state) => choose(state, data),\n          variant: "primary",\n          disabled: state.selected === null,\n        }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null) {\n    const { outliers, ...stats } = state.stats[state.selected]\n    return submit({ label: data.groups[state.selected].label, index: state.selected, ...stats })\n  }\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  if (pointer.kind !== "up") return state\n  const hit = locate(data, layout(state, data, pointer.width, pointer.height), pointer.x, pointer.y)\n  return { ...state, selected: hit === state.selected ? null : hit }\n}\n\nfunction draw(state, data, frame) {\n  const g = ui.draw()\n  const box = layout(state, data, frame.width, frame.height)\n  const hover = frame.pointer && !frame.pointer.down ? locate(data, box, frame.pointer.x, frame.pointer.y) : null\n  const active = hover ?? state.selected\n  for (const tick of box.range.ticks) {\n    const at = y(box, tick)\n    g.line(box.plot.x, at, box.plot.x + box.plot.w, at, { stroke: "border", width: 1 })\n    g.text(box.plot.x - 8, at + 4, compact(tick), { size: 11, align: "right", color: "muted" })\n  }\n  const grow = ease(frame.t / INTRO)\n  data.groups.forEach((group, index) => {\n    const stats = state.stats[index]\n    const color = group.color ?? PALETTE[index % PALETTE.length]\n    const cx = box.plot.x + box.slot * (index + 0.5)\n    const half = Math.min(28, box.slot * 0.3)\n    const median = y(box, stats.median)\n    const at = (value) => median + (y(box, value) - median) * grow\n    g.text(cx, box.plot.y + box.plot.h + 18, fit(group.label, box.slot - 4, 11), {\n      size: 11,\n      align: "center",\n      weight: index === active ? 600 : 400,\n      color: index === active ? "text" : "muted",\n    })\n    const dim = active !== null && active !== index\n    if (dim) g.save().alpha(0.45)\n    g.line(cx, at(stats.max), cx, at(stats.q3), { stroke: color, width: 1.5 })\n    g.line(cx, at(stats.q1), cx, at(stats.min), { stroke: color, width: 1.5 })\n    g.line(cx - half / 2, at(stats.max), cx + half / 2, at(stats.max), { stroke: color, width: 1.5 })\n    g.line(cx - half / 2, at(stats.min), cx + half / 2, at(stats.min), { stroke: color, width: 1.5 })\n    g.save()\n      .alpha(dim ? 0.12 : 0.25)\n      .rect(cx - half, at(stats.q3), half * 2, at(stats.q1) - at(stats.q3), color)\n      .restore()\n    g.rect(cx - half, at(stats.q3), half * 2, Math.max(1, at(stats.q1) - at(stats.q3)), {\n      stroke: color,\n      width: index === active ? 2.5 : 1.5,\n    })\n    g.line(cx - half, median, cx + half, median, { stroke: color, width: 3 })\n    if (frame.t >= INTRO)\n      for (const value of stats.outliers.slice(0, 40)) g.circle(cx, y(box, value), 3, { stroke: color, width: 1.5 })\n    if (dim) g.restore()\n  })\n  return g.commands\n}\n\n// Quartiles by linear interpolation; whiskers at the furthest values within 1.5 × IQR of the box.\nfunction measure(values) {\n  const sorted = [...values].sort((a, b) => a - b)\n  const n = sorted.length\n  const quantile = (q) => {\n    const at = (n - 1) * q\n    const low = Math.floor(at)\n    return sorted[low] + (sorted[Math.min(n - 1, low + 1)] - sorted[low]) * (at - low)\n  }\n  const q1 = quantile(0.25)\n  const q3 = quantile(0.75)\n  const fence = 1.5 * (q3 - q1)\n  const inside = sorted.filter((value) => value >= q1 - fence && value <= q3 + fence)\n  const round = (value) => Math.round(value * 1e6) / 1e6\n  return {\n    n,\n    min: inside[0],\n    q1: round(q1),\n    median: round(quantile(0.5)),\n    q3: round(q3),\n    max: inside[inside.length - 1],\n    mean: round(sorted.reduce((sum, value) => sum + value, 0) / n),\n    outliers: sorted.filter((value) => value < q1 - fence || value > q3 + fence),\n  }\n}\n\nfunction layout(state, data, width, height) {\n  const all = state.stats.flatMap((stats) => [stats.min, stats.max, ...stats.outliers])\n  const range = nice(Math.min(...all), Math.max(...all))\n  const left = 14 + 7 * Math.max(...range.ticks.map((tick) => compact(tick).length))\n  const plot = { x: left, y: 12, w: Math.max(1, width - left - 10), h: Math.max(1, height - 12 - 26) }\n  return { plot, range, slot: plot.w / data.groups.length }\n}\n\nfunction nice(min, max) {\n  const span = max - min || Math.abs(max) || 1\n  const raw = span / 4\n  const power = Math.pow(10, Math.floor(Math.log10(raw)))\n  const step = power * ([1, 2, 2.5, 5, 10].find((factor) => factor * power >= raw) ?? 10)\n  const low = Math.floor(min / step) * step\n  const high = Math.max(low + step, Math.ceil(max / step) * step)\n  const ticks = []\n  for (let tick = low; tick <= high + step / 2; tick += step) ticks.push(Math.round(tick / step) * step)\n  return { low, high, ticks }\n}\n\nfunction y(box, value) {\n  return box.plot.y + box.plot.h * (1 - (value - box.range.low) / (box.range.high - box.range.low))\n}\n\nfunction locate(data, box, px, py) {\n  if (px < box.plot.x || px > box.plot.x + box.plot.w || py < 0 || py > box.plot.y + box.plot.h + 24) return null\n  return Math.max(0, Math.min(data.groups.length - 1, Math.floor((px - box.plot.x) / box.slot)))\n}\n\nfunction describe(state, data, index) {\n  const stats = state.stats[index]\n  const unit = data.unit\n  return (\n    data.groups[index].label +\n    ": median " +\n    amount(stats.median, unit) +\n    ", IQR " +\n    compact(stats.q1) +\n    "–" +\n    amount(stats.q3, unit) +\n    ", whiskers " +\n    compact(stats.min) +\n    "–" +\n    amount(stats.max, unit) +\n    (stats.n !== undefined ? ", n = " + stats.n : "") +\n    (stats.outliers.length\n      ? ", " + stats.outliers.length + (stats.outliers.length === 1 ? " outlier" : " outliers")\n      : "")\n  )\n}\n\nfunction summary(state, data) {\n  return "Box plots. " + data.groups.map((_, index) => describe(state, data, index)).join("; ")\n}\n\nfunction amount(value, unit) {\n  const text = compact(value)\n  if (!unit) return text\n  return unit.length > 1 && /^[a-z]/i.test(unit) ? text + " " + unit : text + unit\n}\n\nfunction compact(value) {\n  const size = Math.abs(value)\n  const round = (number) => String(Math.round(number * 10) / 10)\n  if (size >= 1e9) return round(value / 1e9) + "B"\n  if (size >= 1e6) return round(value / 1e6) + "M"\n  if (size >= 1e4) return round(value / 1e3) + "k"\n  return String(Math.round(value * 100) / 100)\n}\n\nfunction fit(text, width, size) {\n  const max = Math.max(1, Math.floor(width / (size * 0.58)))\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n'
export const flowchart =
  '// A flowchart: nodes (process, decision, terminal, io) and directed edges, laid out top down in layers. `init` does\n// the layout once (Sugiyama style: reverse cycle edges, longest-path layers, dummy points on long edges, barycenter\n// ordering, then x positions pulled toward neighbors) in slot units, so draws only scale it. Layers fade in; tap a node\n// to highlight its edges. With `choose`, the Choose button submits the selected node.\n\nconst LAYER = 84\n\nfunction init(data) {\n  return { selected: null, ...arrange(data) }\n}\n\nfunction view(state, data) {\n  const picked = state.selected === null ? null : data.nodes[state.selected]\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: state.layers * LAYER - 20,\n      fps: 60,\n      duration: intro(state),\n      alt: summary(data),\n    }),\n    ui.text(picked ? describe(data, state.selected) : "Tap a step to follow its edges", {\n      style: "caption",\n      tone: picked ? "default" : "muted",\n    }),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button("Choose step", { onPress: (state) => choose(state, data), variant: "primary", disabled: !picked }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null) {\n    const node = data.nodes[state.selected]\n    return submit({ id: node.id, label: node.label ?? node.id })\n  }\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  if (pointer.kind !== "up") return state\n  const boxes = place(state, data, pointer.width)\n  const hit = boxes.findIndex(\n    (box) => Math.abs(pointer.x - box.x) <= box.w / 2 + 4 && Math.abs(pointer.y - box.y) <= box.h / 2 + 4,\n  )\n  return { ...state, selected: hit < 0 || hit === state.selected ? null : hit }\n}\n\nfunction draw(state, data, frame) {\n  const g = ui.draw()\n  const boxes = place(state, data, frame.width)\n  const columns = grid(state, frame.width)\n  const hover =\n    frame.pointer && !frame.pointer.down\n      ? boxes.findIndex(\n          (box) => Math.abs(frame.pointer.x - box.x) <= box.w / 2 && Math.abs(frame.pointer.y - box.y) <= box.h / 2,\n        )\n      : -1\n  const active = hover >= 0 ? hover : state.selected\n  const step = intro(state) / Math.max(1, state.layers)\n  for (let layer = 0; layer < state.layers; layer++) {\n    const fade = ease((frame.t - layer * step * 0.8) / (step * 1.6))\n    if (fade <= 0) break\n    g.save().alpha(fade)\n    state.edges.forEach((edge, index) => {\n      const from = data.edges[index]\n      const ends = [state.ids[from.from], state.ids[from.to]]\n      if (Math.max(boxes[ends[0]].layer, boxes[ends[1]].layer) !== layer) return\n      const lit = active !== null && ends.includes(active)\n      connect(g, edge, ends, boxes, columns, from.label, lit, frame.t >= intro(state))\n    })\n    data.nodes.forEach((node, index) => {\n      if (boxes[index].layer === layer) shape(g, node, boxes[index], index === active, index === state.selected)\n    })\n    g.restore()\n  }\n  return g.commands\n}\n\n// Layered layout in slot units: every node and dummy point gets a layer and an x; edges keep their point chains.\nfunction arrange(data) {\n  const ids = Object.fromEntries(data.nodes.map((node, at) => [node.id, at]))\n  for (const edge of data.edges)\n    for (const id of [edge.from, edge.to])\n      if (ids[id] === undefined) throw new Error(\'Unknown node id "\' + id + \'" in edges\')\n  const n = data.nodes.length\n  const pairs = data.edges.map((edge) => [ids[edge.from], ids[edge.to]])\n  // Depth-first from the sources; an edge back onto the stack closes a cycle and is reversed for layering.\n  const seen = new Array(n).fill(0)\n  const back = new Set()\n  const visit = (node) => {\n    seen[node] = 1\n    pairs.forEach(([a, b], edge) => {\n      if (a !== node || a === b) return\n      if (seen[b] === 1) back.add(edge)\n      else if (seen[b] === 0) visit(b)\n    })\n    seen[node] = 2\n  }\n  const sources = data.nodes.map((_, at) => at).filter((at) => !pairs.some(([a, b]) => b === at && a !== b))\n  for (const start of [...sources, ...data.nodes.map((_, at) => at)]) if (seen[start] === 0) visit(start)\n  const dag = pairs.map(([a, b], edge) => (back.has(edge) ? [b, a] : [a, b]))\n  const layer = new Array(n).fill(0)\n  for (let pass = 0; pass < n; pass++)\n    for (const [a, b] of dag) if (a !== b && layer[b] < layer[a] + 1) layer[b] = layer[a] + 1\n  // Items are nodes, then one dummy per layer an edge skips; each edge becomes a chain of items.\n  const items = data.nodes.map((_, at) => ({ layer: layer[at], x: 0 }))\n  const chains = dag.map(([a, b]) => {\n    const chain = [a]\n    for (let at = layer[a] + 1; at < layer[b]; at++) {\n      items.push({ layer: at, x: 0 })\n      chain.push(items.length - 1)\n    }\n    chain.push(b)\n    return chain\n  })\n  const up = items.map(() => [])\n  const down = items.map(() => [])\n  for (const chain of chains)\n    for (let at = 1; at < chain.length; at++) {\n      if (chain[at - 1] === chain[at]) continue\n      down[chain[at - 1]].push(chain[at])\n      up[chain[at]].push(chain[at - 1])\n    }\n  const layers = Math.max(...layer) + 1\n  const rows = []\n  for (let at = 0; at < layers; at++)\n    rows.push(items.map((_, index) => index).filter((index) => items[index].layer === at))\n  // Barycenter ordering, alternating downward and upward sweeps.\n  const position = items.map(() => 0)\n  const number = () => rows.forEach((row) => row.forEach((item, at) => (position[item] = at)))\n  number()\n  for (let sweep = 0; sweep < 8; sweep++) {\n    const downward = sweep % 2 === 0\n    for (const row of downward ? rows : [...rows].reverse()) {\n      const score = (item) => {\n        const near = downward ? up[item] : down[item]\n        return near.length ? near.reduce((sum, other) => sum + position[other], 0) / near.length : position[item]\n      }\n      const scores = new Map(row.map((item) => [item, score(item)]))\n      row.sort((a, b) => scores.get(a) - scores.get(b))\n      row.forEach((item, at) => (position[item] = at))\n    }\n  }\n  // x: start packed and centered, then pull toward neighbors while keeping the order and a minimum gap.\n  rows.forEach((row) => row.forEach((item, at) => (items[item].x = at - (row.length - 1) / 2)))\n  const gap = (a, b) => (a < n && b < n ? 1 : a < n || b < n ? 0.6 : 0.3)\n  for (let pass = 0; pass < 8; pass++) {\n    const downward = pass % 2 === 0\n    for (const row of downward ? rows : [...rows].reverse()) {\n      const desired = row.map((item) => {\n        const near = [...(downward ? up[item] : down[item])]\n        return near.length ? near.reduce((sum, other) => sum + items[other].x, 0) / near.length : items[item].x\n      })\n      const xs = [...desired]\n      for (let at = 1; at < row.length; at++) xs[at] = Math.max(xs[at], xs[at - 1] + gap(row[at - 1], row[at]))\n      const shift = desired.reduce((sum, value, at) => sum + value - xs[at], 0) / row.length\n      row.forEach((item, at) => (items[item].x = xs[at] + shift))\n    }\n  }\n  const min = Math.min(...items.map((item) => item.x))\n  const round = (value) => Math.round((value - min) * 1000) / 1000\n  return {\n    ids,\n    layers,\n    span: Math.max(...items.map((item) => item.x)) - min,\n    nodes: items.slice(0, n).map((item) => ({ x: round(item.x), layer: item.layer })),\n    edges: chains.map((chain, edge) => {\n      const points = chain.map((item) => [round(items[item].x), items[item].layer])\n      return { points: back.has(edge) ? points.reverse() : points, self: pairs[edge][0] === pairs[edge][1] }\n    }),\n  }\n}\n\n// Slot units to pixels: at most 190 px per slot, the whole span centered in the width.\nfunction grid(state, width) {\n  const unit = Math.min(190, (width - 16) / (state.span + 1))\n  const left = (width - unit * (state.span + 1)) / 2\n  return { unit, x: (slot) => left + (slot + 0.5) * unit, y: (layer) => 10 + layer * LAYER + 22 }\n}\n\nfunction place(state, data, width) {\n  const columns = grid(state, width)\n  const unit = columns.unit\n  return data.nodes.map((node, index) => {\n    const lines = wrap(node.label ?? node.id, Math.floor((Math.min(170, unit - 14) - 16) / 6.8))\n    const decision = node.shape === "decision"\n    const text = Math.max(...lines.map((line) => line.length)) * 6.8 + 24\n    const w = Math.min(unit - 8, decision ? text * 1.4 + 10 : text)\n    const h = decision ? 54 : lines.length > 1 ? 44 : 34\n    const at = state.nodes[index]\n    return { x: columns.x(at.x), y: columns.y(at.layer), w, h, lines, layer: at.layer }\n  })\n}\n\nfunction shape(g, node, box, active, selected) {\n  const paint = {\n    fill: "surface",\n    stroke: selected ? "accent" : active ? "muted" : (node.color ?? "border"),\n    width: selected ? 2 : 1.25,\n  }\n  const left = box.x - box.w / 2\n  const top = box.y - box.h / 2\n  if (node.shape === "decision")\n    g.path(\n      [["M", box.x, top], ["L", box.x + box.w / 2, box.y], ["L", box.x, top + box.h], ["L", left, box.y], ["Z"]],\n      paint,\n    )\n  else if (node.shape === "io")\n    g.path(\n      [\n        ["M", left + 8, top],\n        ["L", left + box.w, top],\n        ["L", left + box.w - 8, top + box.h],\n        ["L", left, top + box.h],\n        ["Z"],\n      ],\n      paint,\n    )\n  else g.rrect(left, top, box.w, box.h, node.shape === "terminal" ? box.h / 2 : 6, paint)\n  box.lines.forEach((line, at) =>\n    g.text(box.x, box.y + 4 + (at - (box.lines.length - 1) / 2) * 15, line, {\n      size: 12,\n      align: "center",\n      weight: node.shape === "terminal" ? 600 : 400,\n    }),\n  )\n}\n\n// An edge through its points: leave a node from its bottom (or top, going up), curve through dummies, arrive with an arrow.\nfunction connect(g, edge, ends, boxes, columns, label, lit, labels) {\n  const stroke = lit ? "accent" : "muted"\n  const width = lit ? 2 : 1.25\n  const from = boxes[ends[0]]\n  if (edge.self) {\n    const x = from.x + from.w / 2\n    g.path(\n      [\n        ["M", x, from.y - 6],\n        ["C", x + 30, from.y - 22, x + 30, from.y + 22, x + 2, from.y + 6],\n      ],\n      { stroke, width },\n    )\n    return\n  }\n  const points = edge.points.map(([x, layer], at) => {\n    const real = at === 0 ? boxes[ends[0]] : at === edge.points.length - 1 ? boxes[ends[1]] : null\n    return real ? { x: real.x, y: real.y, h: real.h } : { x: columns.x(x), y: columns.y(layer), h: 0 }\n  })\n  const start = points[1].y > points[0].y ? 1 : -1\n  let x0 = points[0].x\n  let y0 = points[0].y + (start * points[0].h) / 2\n  const segments = [["M", x0, y0]]\n  for (let at = 1; at < points.length; at++) {\n    const p = points[at]\n    const dir = p.y > points[at - 1].y ? 1 : -1\n    const y1 = p.y - (dir * p.h) / 2 - (at === points.length - 1 ? dir * 2 : 0)\n    const bend = (y1 - y0) / 2\n    segments.push(["C", x0, y0 + bend, p.x, y1 - bend, p.x, y1])\n    x0 = p.x\n    y0 = y1\n  }\n  g.path(segments, { stroke, width })\n  const tip = segments[segments.length - 1]\n  const dir = points[points.length - 1].y > points[points.length - 2].y ? 1 : -1\n  const tx = tip[5]\n  const ty = tip[6] + dir * 2\n  g.path([["M", tx, ty], ["L", tx - 4.5, ty - dir * 8], ["L", tx + 4.5, ty - dir * 8], ["Z"]], stroke)\n  if (label && labels) {\n    const first = segments[1]\n    const mx = (segments[0][1] + first[5]) / 2\n    const my = (segments[0][2] + first[6]) / 2\n    const w = 6.4 * label.length + 10\n    g.rrect(mx - w / 2, my - 9, w, 16, 4, "bg")\n    g.text(mx, my + 3, label, { size: 11, align: "center", color: lit ? "text" : "muted" })\n  }\n}\n\nfunction intro(state) {\n  return Math.round(Math.min(1.6, 0.3 + 0.15 * state.layers) * 100) / 100\n}\n\n// Splits a label into at most two lines of about `max` characters.\nfunction wrap(label, max) {\n  if (label.length <= max) return [label]\n  const words = label.split(" ")\n  let first = ""\n  while (words.length && (first + " " + words[0]).trim().length <= max) first = (first + " " + words.shift()).trim()\n  if (!first) first = words.shift()\n  const rest = words.join(" ")\n  return [fit(first, max), rest ? fit(rest, max) : null].filter(Boolean)\n}\n\nfunction describe(data, index) {\n  const node = data.nodes[index]\n  const name = (id) => data.nodes.find((item) => item.id === id)?.label ?? id\n  const next = data.edges\n    .filter((edge) => edge.from === node.id)\n    .map((edge) => name(edge.to) + (edge.label ? " (" + edge.label + ")" : ""))\n  const previous = data.edges.filter((edge) => edge.to === node.id).map((edge) => name(edge.from))\n  return [\n    node.label ?? node.id,\n    next.length ? "next: " + next.join(", ") : "",\n    previous.length ? "from: " + previous.join(", ") : "",\n  ]\n    .filter(Boolean)\n    .join(" · ")\n}\n\nfunction summary(data) {\n  const name = (id) => data.nodes.find((item) => item.id === id)?.label ?? id\n  return (\n    "Flowchart. " +\n    data.edges\n      .map((edge) => name(edge.from) + " → " + (edge.label ? "[" + edge.label + "] " : "") + name(edge.to))\n      .join("; ")\n  )\n}\n\nfunction fit(text, max) {\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n'
export const sequence =
  '// A sequence diagram: participants as columns with lifelines and messages between them, top to bottom in order.\n// Kinds: "sync" (solid, filled arrow), "async" (solid, open arrow) and "reply" (dashed, open arrow); a message to\n// itself loops back. Messages play in one after another; tap one to select it. With `choose`, the Choose button submits it.\n\nconst HEAD = 34\nconst ROW = 36\n\nfunction init(data) {\n  for (const message of data.messages) [message.from, message.to].forEach((name) => participant(data, name))\n  return { selected: null }\n}\n\nfunction view(state, data) {\n  const picked = state.selected === null ? null : data.messages[state.selected]\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.canvas({\n      onPointer: (state, p) => tap(state, data, p),\n      height: HEAD + 14 + data.messages.length * ROW + 8,\n      fps: 60,\n      duration: intro(data),\n      alt: summary(data),\n    }),\n    ui.text(picked ? describe(data, state.selected) : "Tap a message to select it", {\n      style: "caption",\n      tone: picked ? "default" : "muted",\n    }),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button("Choose message", { onPress: (state) => choose(state, data), variant: "primary", disabled: !picked }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected !== null) {\n    const message = data.messages[state.selected]\n    return submit({ index: state.selected, from: message.from, to: message.to, label: message.label })\n  }\n  return state\n}\n\nfunction tap(state, data, pointer) {\n  pointer = below(pointer)\n  if (pointer.kind !== "up") return state\n  const hit = locate(data, pointer.y)\n  return { ...state, selected: hit === state.selected ? null : hit }\n}\n\nfunction draw(state, data, frame) {\n  frame = below(frame)\n  const g = ui.draw()\n  if (frame.top) g.translate(0, frame.top)\n  const columns = layout(data, frame.width)\n  const bottom = frame.height - 4\n  const hover = frame.pointer && !frame.pointer.down ? locate(data, frame.pointer.y) : null\n  columns.forEach((column) => {\n    g.path(dashes(column.x, HEAD, column.x, bottom, 4, 4), { stroke: "border", width: 1 })\n    g.rrect(column.x - column.w / 2, 2, column.w, HEAD - 6, 6, { fill: "surface", stroke: "border", width: 1 })\n    g.text(column.x, HEAD / 2 + 3, column.label, { size: 12, weight: 600, align: "center" })\n  })\n  const step = (intro(data) - 0.5) / Math.max(1, data.messages.length - 1)\n  data.messages.forEach((message, index) => {\n    const grow = ease((frame.t - 0.2 - index * step) / 0.3)\n    if (grow <= 0) return\n    const y = HEAD + 14 + index * ROW + ROW / 2 + 6\n    const from = columns[participant(data, message.from)].x\n    const to = columns[participant(data, message.to)].x\n    const active = index === state.selected || index === hover\n    if (index === state.selected)\n      g.save()\n        .alpha(0.08)\n        .rect(0, y - ROW + 8, frame.width, ROW, "text")\n        .restore()\n    const stroke = active ? "accent" : message.kind === "reply" ? "muted" : "text"\n    const width = active ? 2 : 1.25\n    const kind = message.kind ?? "sync"\n    g.save().alpha(grow)\n    if (from === to) {\n      const loop = Math.min(36, frame.width - from - 8)\n      g.path(\n        [\n          ["M", from, y - 8],\n          ["L", from + loop, y - 8],\n          ["L", from + loop, y + 6],\n          ["L", from + 2, y + 6],\n        ],\n        { stroke, width },\n      )\n      head(g, from + 2, y + 6, -1, stroke, kind)\n      g.text(from + loop + 6, y + 2, fit(number(data, index) + message.label, frame.width - from - loop - 10, 12), {\n        size: 12,\n        color: active ? "text" : "muted",\n      })\n    } else {\n      const dir = to > from ? 1 : -1\n      const end = from + (to - from) * grow\n      if (kind === "reply") g.path(dashes(from, y, end - dir * 2, y, 6, 4), { stroke, width })\n      else g.line(from, y, end - dir * 2, y, { stroke, width })\n      if (grow >= 1) head(g, to, y, dir, stroke, kind)\n      g.text((from + to) / 2, y - 6, fit(number(data, index) + message.label, Math.abs(to - from) - 12, 12), {\n        size: 12,\n        align: "center",\n        weight: active ? 600 : 400,\n        color: active ? "text" : kind === "reply" ? "muted" : "text",\n      })\n    }\n    g.restore()\n  })\n  return g.commands\n}\n\nfunction layout(data, width) {\n  const slot = (width - 8) / data.participants.length\n  return data.participants.map((name, index) => ({\n    label: fit(name, slot - 20, 12),\n    x: 4 + slot * (index + 0.5),\n    w: Math.min(slot - 10, 7.2 * name.length + 22),\n  }))\n}\n\nfunction participant(data, name) {\n  const index = data.participants.indexOf(name)\n  if (index < 0) throw new Error(\'Unknown participant "\' + name + \'" in messages\')\n  return index\n}\n\nfunction locate(data, y) {\n  const index = Math.floor((y - HEAD - 14) / ROW)\n  return index >= 0 && index < data.messages.length ? index : null\n}\n\n// One path of dash segments: a single draw command however long the line is.\nfunction dashes(x1, y1, x2, y2, on, off) {\n  const length = Math.hypot(x2 - x1, y2 - y1)\n  const dx = (x2 - x1) / (length || 1)\n  const dy = (y2 - y1) / (length || 1)\n  const segments = []\n  for (let at = 0; at < length; at += on + off) {\n    const stop = Math.min(length, at + on)\n    segments.push(["M", x1 + dx * at, y1 + dy * at], ["L", x1 + dx * stop, y1 + dy * stop])\n  }\n  return segments\n}\n\nfunction head(g, x, y, dir, stroke, kind) {\n  if (kind === "sync") g.path([["M", x, y], ["L", x - dir * 9, y - 4.5], ["L", x - dir * 9, y + 4.5], ["Z"]], stroke)\n  else\n    g.path(\n      [\n        ["M", x - dir * 9, y - 5],\n        ["L", x, y],\n        ["L", x - dir * 9, y + 5],\n      ],\n      { stroke, width: 1.5 },\n    )\n}\n\nfunction intro(data) {\n  return Math.round(Math.min(2.4, 0.5 + 0.12 * data.messages.length) * 100) / 100\n}\n\nfunction number(data, index) {\n  return data.numbered ? index + 1 + ". " : ""\n}\n\nfunction describe(data, index) {\n  const message = data.messages[index]\n  return (\n    index +\n    1 +\n    ". " +\n    message.from +\n    " → " +\n    message.to +\n    ": " +\n    message.label +\n    (message.kind && message.kind !== "sync" ? " (" + message.kind + ")" : "")\n  )\n}\n\nfunction summary(data) {\n  return (\n    "Sequence diagram between " +\n    data.participants.join(", ") +\n    ". " +\n    data.messages.map((_, index) => describe(data, index)).join("; ")\n  )\n}\n\nfunction fit(text, width, size) {\n  const max = Math.max(1, Math.floor(width / (size * 0.58)))\n  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + "…"\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n\n// In full screen, the layout starts below the close button when it overlaps this canvas (widgets-fullscreen.md):\n// `close` comes with the frame and the pointer, so drawing and hit testing agree.\nfunction below(area) {\n  const top = area.close ? Math.max(0, area.close.y + area.close.height) : 0\n  if (top === 0) return area\n  return {\n    ...area,\n    top,\n    height: area.height - top,\n    ...(typeof area.y === "number" ? { y: area.y - top } : {}),\n    ...(area.pointer ? { pointer: { ...area.pointer, y: area.pointer.y - top } } : {}),\n  }\n}\n'
export const table =
  '// A sortable table built from regular nodes: each row is one monospace line so columns line up in every client (the\n// TUI included), sort buttons above, and a small canvas sparkline per row for its `trend`. With `choose`, rows become\n// selectable cards and the Choose button submits the selected row.\n\nconst SPARK_WIDTH = 96\nconst SPARK_HEIGHT = 22\nconst INTRO = 0.6\nconst MAX_WIDTH = 28\n\nfunction init(data) {\n  return { sort: null, desc: false, selected: null }\n}\n\nfunction view(state, data) {\n  // Once per view: every cell formatted, and per column its width and whether it\'s numeric. A row\'s line must not\n  // rescan the rows (that made views O(rows²)).\n  const cells = data.rows.map((row) => data.columns.map((_, index) => text(data, index, row.cells[index])))\n  const widths = measure(data, cells)\n  const numbers = data.columns.map((_, index) => numeric(data, index))\n  const trend = data.rows.some((row) => row.trend)\n  // Rows are keyed by their index in `data.rows`, so sorting keeps each row\'s ids.\n  const wrap = (index, children) =>\n    data.choose && index !== null\n      ? ui.card(\n          {\n            key: index,\n            selected: state.selected === index,\n            onPress: (state) => ({ ...state, selected: state.selected === index ? null : index }),\n          },\n          [ui.row({ gap: 1, align: "center", wrap: true }, children)],\n        )\n      : ui.row({ key: index ?? "header", gap: 1, align: "center", wrap: true }, children)\n  const picked = state.selected === null ? null : data.rows[state.selected]\n  return ui.column({ gap: 1, align: "stretch" }, [\n    ui.text(data.title, { style: "title" }),\n    ui.row({ gap: 1, align: "center", wrap: true }, [\n      ui.text("Sort by", { style: "caption", tone: "muted" }),\n      data.columns.map((column, index) =>\n        ui.button(column.label + (state.sort === index ? (state.desc ? " ↓" : " ↑") : ""), {\n          variant: state.sort === index ? "primary" : "secondary",\n          onPress: (state) =>\n            state.sort === index\n              ? { ...state, desc: !state.desc }\n              : { ...state, sort: index, desc: numeric(data, index) },\n        }),\n      ),\n    ]),\n    wrap(null, [\n      ui.text(\n        line(\n          widths,\n          numbers,\n          data.columns.map((column) => column.label),\n        ),\n        { style: "code", tone: "muted" },\n      ),\n      trend && ui.text(data.trendLabel ?? "Trend", { style: "caption", tone: "muted" }),\n    ]),\n    !data.choose && ui.divider(),\n    order(state, data).map((index) =>\n      wrap(index, [\n        ui.text(line(widths, numbers, cells[index]), { style: "code" }),\n        trend &&\n          data.rows[index].trend &&\n          ui.canvas({\n            key: "spark" + index,\n            width: SPARK_WIDTH,\n            height: SPARK_HEIGHT,\n            fps: 60,\n            duration: INTRO,\n            alt: (data.trendLabel ?? "Trend") + ": " + data.rows[index].trend.map(compact).join(", "),\n          }),\n      ]),\n    ),\n    data.choose &&\n      ui.row({ gap: 1 }, [\n        ui.button(picked ? "Choose " + text(data, 0, picked.cells[0]) : "Choose", {\n          variant: "primary",\n          disabled: !picked,\n          onPress: (state) => choose(state, data),\n        }),\n      ]),\n  ])\n}\n\nfunction choose(state, data) {\n  if (state.selected === null) return state\n  const row = data.rows[state.selected]\n  return submit({\n    index: state.selected,\n    row: Object.fromEntries(data.columns.map((column, at) => [column.label, row.cells[at] ?? null])),\n  })\n}\n\n// A sparkline: the trend as a line over a faint area, drawn in from the left, with the last value marked.\nfunction draw(state, data, frame) {\n  const g = ui.draw()\n  const values = data.rows[Number(frame.key.slice(5))].trend\n  const min = Math.min(...values)\n  const span = Math.max(...values) - min || 1\n  const x = (index) => 3 + ((frame.width - 6) * index) / Math.max(1, values.length - 1)\n  const y = (value) => 3 + (frame.height - 6) * (1 - (value - min) / span)\n  const shown = Math.max(1, Math.ceil(ease(frame.t / INTRO) * values.length))\n  const points = values.slice(0, shown).map((value, index) => [index === 0 ? "M" : "L", x(index), y(value)])\n  const stroke = data.color ?? "accent"\n  if (points.length > 1)\n    g.save()\n      .alpha(0.15)\n      .path([...points, ["L", x(shown - 1), frame.height], ["L", x(0), frame.height], ["Z"]], stroke)\n      .restore()\n  g.path(points, { stroke, width: 1.5, cap: "round" })\n  if (shown === values.length) g.circle(x(shown - 1), y(values[shown - 1]), 2.5, stroke)\n  return g.commands\n}\n\n// Row indices in display order: stable, numbers by value, text case-insensitively, empty cells last.\nfunction order(state, data) {\n  const indices = data.rows.map((_, index) => index)\n  if (state.sort === null) return indices\n  const key = (index) => {\n    const cell = data.rows[index].cells[state.sort]\n    return typeof cell === "string" ? cell.toLowerCase() : cell\n  }\n  return indices.sort((a, b) => {\n    const left = key(a)\n    const right = key(b)\n    if (left === right) return a - b\n    if (left === undefined || left === null) return 1\n    if (right === undefined || right === null) return -1\n    return (left < right ? -1 : 1) * (state.desc ? -1 : 1)\n  })\n}\n\nfunction numeric(data, column) {\n  return data.rows.every((row) => typeof (row.cells[column] ?? 0) === "number")\n}\n\n// Character widths of each column: the longest of the label and the formatted cells, capped at MAX_WIDTH.\nfunction measure(data, cells) {\n  return data.columns.map((column, index) =>\n    Math.min(\n      MAX_WIDTH,\n      cells.reduce((widest, row) => Math.max(widest, row[index].length), column.label.length),\n    ),\n  )\n}\n\n// One line of already formatted cells, cut and padded to the column widths.\nfunction line(widths, numbers, cells) {\n  return cells\n    .map((value, index) => {\n      const cell = value.length > widths[index] ? value.slice(0, widths[index] - 1) + "…" : value\n      return numbers[index] ? cell.padStart(widths[index]) : cell.padEnd(widths[index])\n    })\n    .join("  ")\n}\n\nfunction text(data, index, cell) {\n  if (cell === undefined || cell === null) return "–"\n  if (typeof cell === "string") return cell\n  const column = data.columns[index]\n  const digits = column.digits ?? (Number.isInteger(cell) ? 0 : 2)\n  const [whole, fraction] = Math.abs(cell).toFixed(digits).split(".")\n  const number = (cell < 0 ? "-" : "") + whole.replace(/\\B(?=(\\d{3})+(?!\\d))/g, ",") + (fraction ? "." + fraction : "")\n  const unit = column.unit\n  if (!unit) return number\n  if (/^[$€£¥]$/.test(unit)) return (cell < 0 ? "-" : "") + unit + number.replace("-", "")\n  return unit.length > 1 && /^[a-z]/i.test(unit) ? number + " " + unit : number + unit\n}\n\nfunction compact(value) {\n  return String(Math.round(value * 100) / 100)\n}\n\nfunction ease(p) {\n  const clamped = Math.max(0, Math.min(1, p))\n  return 1 - Math.pow(1 - clamped, 3)\n}\n'
